```python
"""A stopwatch over timestamps the caller supplies (seconds)."""


class Clock:
    def __init__(self):
        self.start = None
        self.stop = None

    def begin(self, at):
        self.start = at
        self.stop = None

    def finish(self, at):
        self.stop = at

    def elapsed_ms(self):
        if self.start is None or self.stop is None:
            return 0
        return (self.stop - self.start) * 1000
```

